Copy the workbook, add an AutoFilter to raw 1!A1:C1, and compute per-class counts from raw 1 rows 2 through 100000.  
For each value in F4:F8, count rows where A matches that value and the original COUNTIFS condition holds: B>0 with C<0 or C=0, or B=0 with C<0.  
Write the five integer counts to G4:G8 as plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

SHEET = "raw 1"
ws = wb[SHEET]
vws = vals[SHEET]

# Add filter to A1:C1 as requested.
ws.auto_filter.ref = "A1:C1"

def norm_key(x):
    if x is None:
        return None
    if isinstance(x, str):
        return x.lower()
    return x

def to_num(x):
    if x is None:
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return 0.0
        try:
            return float(s)
        except ValueError:
            return None
    return None

# F4:F8 are the class labels for G4:G8.
fkeys = [norm_key(vws.cell(row=r, column=6).value) for r in range(4, 9)]

key_to_idx = {}
for i, k in enumerate(fkeys):
    key_to_idx.setdefault(k, []).append(i)

counts = [0] * len(fkeys)

# Original formula range is rows 2:100000.
max_row = min(vws.max_row or 1, 100000)

for r in range(2, max_row + 1):
    a = norm_key(vws.cell(row=r, column=1).value)
    if a is None or a not in key_to_idx:
        continue

    b = to_num(vws.cell(row=r, column=2).value)
    c = to_num(vws.cell(row=r, column=3).value)

    if b is None or c is None:
        continue

    # Equivalent to:
    # COUNTIFS(B, ">0", C, "<0") +
    # COUNTIFS(B, ">0", C, "=0") +
    # COUNTIFS(B, "=0", C, "<0")
    if (b > 0 and c < 0) or (b > 0 and c == 0) or (b == 0 and c < 0):
        for i in key_to_idx[a]:
            counts[i] += 1

for i, _ in enumerate(fkeys):
    ws.cell(row=4 + i, column=7).value = counts[i]

wb.save(OUT)

print("fkeys:", fkeys)
print("counts:", counts)
print("sum:", sum(counts))
